def is_safe_partner(classroom, student, row, col):
    for c in [col - 1, col + 1]:
        if 0 <= c < classroom.cols:
            nb = classroom.seats[row][c]
            if nb is not None and nb.name == student.prev_partner:
                return False
    return True

